import sys, json
# Read all input and find the JSON object
text = sys.stdin.read()
start = text.find('{')
if start >= 0:
    data = json.loads(text[start:])
    with open('after-cpm-packages.json', 'w') as f:
        json.dump(data, f, indent=2)
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                print(f\"{name} [{fw['framework']}]: {pkg['id']} {pkg['resolvedVersion']}\")
